use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use aes::Aes128;
use block_modes::{BlockMode, Cbc};
use block_modes::block_padding::Pkcs7;
use base64;
use hex;
use serde::Deserialize;

type Aes128Cbc = Cbc<Aes128, Pkcs7>;

const AES_KEY: &[u8; 16] = b"supersecretkey!!"; // In production, loaded from Vault

#[derive(Deserialize)]
struct DecryptRequest {
    ciphertext: String,
    iv: String,
}

/// Decrypts user-provided ciphertext and returns the plaintext session data.
/// Used internally by the session-validation sidecar.
async fn decrypt_session(req: HttpRequest, body: web::Json<DecryptRequest>) -> HttpResponse {
    let ct_bytes = match base64::decode(&body.ciphertext) {
        Ok(b) => b,
        Err(_) => return HttpResponse::BadRequest().body("invalid base64 in ciphertext"),
    };

    let iv_bytes = match hex::decode(&body.iv) {
        Ok(b) => b,
        Err(_) => return HttpResponse::BadRequest().body("invalid hex in iv"),
    };

    if iv_bytes.len() != 16 {
        return HttpResponse::BadRequest().body("iv must be 16 bytes");
    }

    // Attempt decryption with PKCS7 padding validation
    let cipher = match Aes128Cbc::new_from_slices(AES_KEY, &iv_bytes) {
        Ok(c) => c,
        Err(_) => return HttpResponse::InternalServerError().body("cipher init failed"),
    };

    match cipher.decrypt_vec(&ct_bytes) {
        Ok(plaintext) => {
            // Padding was valid - return decrypted session
            let session_str = String::from_utf8_lossy(&plaintext);
            HttpResponse::Ok()
                .content_type("application/json")
                .body(format!("{{\"session\": \"{}\"}}", session_str))
        }
        Err(_) => {
            // Padding validation failed - distinct error response
            // This leaks padding validity information
            HttpResponse::UnprocessableEntity()
                .body("decryption failed: invalid padding")
        }
    }
}

/// Health check endpoint (accessible to all)
async fn health() -> HttpResponse {
    HttpResponse::Ok().body("ok")
}

/// Metrics endpoint for Prometheus scraping
async fn metrics() -> HttpResponse {
    HttpResponse::Ok()
        .content_type("text/plain")
        .body("# HELP decrypt_requests_total Total decrypt requests\ndecrypt_requests_total 0\n")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();
    println!("Starting session-decrypt service on :8080");
    println!("Note: This service should only be accessed by session-validator in same namespace");

    HttpServer::new(|| {
        App::new()
            .wrap(middleware::Logger::default())
            .route("/health", web::get().to(health))
            .route("/metrics", web::get().to(metrics))
            .route("/internal/decrypt", web::post().to(decrypt_session))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
